    "method_eyebrow": "Why this works",
    "method_title": "The method behind Étude",
    "method_intro": "Étude isn’t a quiz — it’s built on what cognitive science actually says about learning a skill. Six ideas do the heavy lifting. None of them involve studying harder; they involve studying smarter.",
    "m1n": "Spaced repetition",
    "m1d": "You remember something best when you review it right as you’re about to forget it. Each successful recall lets the next review wait a little longer.",
    "m1a": "every concept carries its own due-date. Today shows what’s due; the schedule stretches as you succeed and snaps back when you slip.",
    "m2n": "Retrieval practice",
    "m2d": "Pulling an answer out of memory strengthens it far more than putting it back in by re-reading. This is the “testing effect.”",
    "m2a": "you always produce the answer — play the interval, build the chord, name what you hear — never just look at a chart.",
    "m3n": "Interleaving",
    "m3d": "Mixing different problem types in one sitting feels harder than doing them in blocks — and that’s exactly why it builds more durable, flexible memory.",
    "m3a": "a session shuffles intervals, chords, scales and progressions together, never two of a kind back to back.",
    "m4n": "Desirable difficulty",
    "m4d": "A little struggle is the signal that learning is happening. Effortless review barely moves the needle.",
    "m4a": "once you can play a concept, it graduates to by ear — and the key changes every time, so you learn the idea, not one fingering.",
    "m5n": "Immediate feedback & elaboration",
    "m5d": "Fast correction stops errors from sticking, and a short “why” ties the new fact to things you already know.",
    "m5a": "every answer is followed by the formula, a familiar-song hook, and how the sound feels — so it lands in context.",
    "m6n": "Little and often",
    "m6d": "The spacing effect: the same total practice spread across days beats one long cram. Short, frequent sessions win.",
    "m6a": "a daily goal and streak keep it to a five-minute habit, and tomorrow’s reviews are always waiting.",
    "method_close": "“We are what we repeatedly do.” The hard part of theory isn’t understanding it once — it’s remembering it under your fingers, months later. That’s the part Étude is for.",
