    "items_sub": "mai cald = memorie mai puternică",
    "method_eyebrow": "De ce funcționează",
    "method_title": "Metoda din spatele Étude",
    "method_intro": "Étude nu e un test — e construit pe ce spune de fapt știința cognitivă despre învățarea unei abilități. Șase idei fac toată treaba. Niciuna nu înseamnă să studiezi mai mult; înseamnă să studiezi mai inteligent.",
    "m1n": "Repetiția eșalonată",
    "m1d": "Reții cel mai bine ceva când îl repeți exact când ești pe cale să-l uiți. Fiecare reamintire reușită lasă următoarea repetiție să aștepte puțin mai mult.",
    "m1a": "fiecare concept are propria dată scadentă. „Azi” arată ce e de repetat; programul se întinde când reușești și revine când greșești.",
    "m2n": "Reactualizarea activă",
    "m2d": "Scoaterea unui răspuns din memorie îl întărește mult mai mult decât recitirea. Acesta e „efectul testării”.",
    "m2a": "produci mereu răspunsul — cânți intervalul, construiești acordul, numești ce auzi — niciodată nu doar te uiți pe o schemă.",
    "m3n": "Întrețeserea",
    "m3d": "Amestecarea tipurilor diferite de probleme într-o ședință pare mai grea decât pe blocuri — și exact de aceea creează o memorie mai durabilă și mai flexibilă.",
    "m3a": "o sesiune amestecă intervale, acorduri, game și progresii, niciodată două la fel una după alta.",
    "m4n": "Dificultatea benefică",
    "m4d": "Un mic efort e semnul că învățarea chiar are loc. Repetiția fără efort aproape că nu schimbă nimic.",
    "m4a": "odată ce poți cânta un concept, trece la „după ureche” — iar tonalitatea se schimbă de fiecare dată, ca să înveți ideea, nu o singură digitație.",
    "m5n": "Feedback imediat și elaborare",
    "m5d": "Corectarea rapidă împiedică fixarea greșelilor, iar un scurt „de ce” leagă noul fapt de lucruri pe care deja le știi.",
    "m5a": "fiecare răspuns e urmat de formulă, de o melodie cunoscută și de felul în care sună — ca să prindă context.",
    "m6n": "Puțin și des",
    "m6d": "Efectul eșalonării: aceeași cantitate de exercițiu împărțită pe zile bate o sesiune lungă de înghesuială. Câștigă sesiunile scurte și dese.",
    "m6a": "un obiectiv zilnic și seria de zile o mențin un obicei de cinci minute, iar repetițiile de mâine te așteaptă mereu.",
    "method_close": "„Suntem ceea ce facem în mod repetat.” Partea grea a teoriei nu e s-o înțelegi o dată — e s-o ții minte sub degete, luni mai târziu. Pentru asta există Étude.",
    "method_cta": "Începe sesiunea de azi →",
