    "ses_keys_hint": "Scurtături: 1–9 alege răspunsul · R ascultă din nou · N următorul",
    "an_limits": "MusicXML (.musicxml, .xml sau .mxl comprimat) păstrează notația sursei. MIDI este reconstruit ca notație pe grila ritmică aleasă (implicit 1/16); mâinile urmează pistele MIDI când se separă clar, altfel se împart după înălțime. Armura din fișier este păstrată; fără ea tonalitatea este estimată și o poți alege manual. Măsura lipsă devine 4/4. Redarea respectă schimbările de tempo; repetițiile nu sunt desfășurate. Fără PDF.",
