    "an_tip": "Tonalitatea este estimată cu profilurile Krumhansl–Kessler ponderate cu durata, deci o tonalitate majoră se distinge de relativa ei minoră; valoarea r arată cât de clar se potrivesc notele. Acordurile sunt comparate pe fiecare timp cu șabloane ponderate cu durata, așa că notele de trecere scad încrederea în loc să strice potrivirea. Cifrele romane urmează tonalitatea scrisă sau aleasă. Apasă un acord sau un motiv pentru a-i selecta notele.",
