    "an_harm_implied": "Este pasaje es una sola línea melódica, por lo que los acordes están implícitos en lugar de interpretados. Se estiman por compás o medio compás y son solo sugerencias.",
    "an_harm_none": "No hay acordes claros en este pasaje.",
    "an_harm_note": "Cada acorde abarca todo el compás salvo que las notas cambien claramente de armonía en un pulso, y se analiza a partir de todas las notas sonantes, ponderadas por duración y peso métrico. Exacto: suenan todas las notas del acorde y ninguna otra lectura se aproxima. Probable: la mejor interpretación, aunque falte una nota, suenen notas extrañas o haya otra lectura cercana. Sugerido: ambiguo; se muestran alternativas. Las notas extrañas se clasifican según su preparación, resolución y enlace con la armonía siguiente.",
