    "an_limits": "MusicXML (.musicxml, .xml o .mxl comprimido) conserva la notación original. El MIDI se reconstruye como partitura sobre la cuadrícula rítmica que elijas (1/16 por defecto); las manos siguen las pistas MIDI cuando se separan con claridad, o bien una división por altura. Se conserva la armadura del archivo; sin ella se estima la tonalidad y puedes cambiarla. Un compás ausente adopta 4/4 por defecto. Se respetan los cambios de tempo en la reproducción; las repeticiones no se despliegan. No admite PDF.",
