    "an_tip": "Las tonalidades se estiman mediante perfiles Krumhansl–Kessler ponderados por duración, distinguiendo entre una tonalidad mayor y su relativa menor; el coeficiente r refleja la claridad del ajuste. Los acordes se comparan pulso a pulso con patrones ponderados por duración, de modo que las notas de paso reducen la confianza en lugar de invalidar la lectura. Los números romanos siguen la tonalidad indicada o seleccionada. Pulsa un acorde o motivo para seleccionar sus notas.",
