    "an_limits": "MusicXML (.musicxml, .xml ou .mxl compressé) conserve la notation source. Le MIDI est reconstruit sous forme de partition sur la grille rythmique de votre choix (1/16 par défaut) ; les mains suivent les pistes MIDI lorsqu’elles sont bien séparées, sinon une coupure de hauteur. L’armure du fichier est conservée ; sans elle, la tonalité est estimée et modifiable. Une métrique manquante vaut 4/4 par défaut. La lecture suit les changements de tempo ; les reprises ne sont pas développées. Pas de PDF.",
