    "rdx_u_cc": "C-Schlüssel",
    "rdx_u_sr": "Blattspiel",
    "rdx_ud_tr": "Von Orientierungsnoten bis zu Hilfslinien — benenne, spiele und finde jeden Ton im Violinschlüssel.",
    "rdx_ud_ba": "Das System der linken Hand, Schritt für Schritt: Orientierungstöne, Linien, Zwischenräume und Hilfslinien.",
    "rdx_ud_gr": "Beide Systeme gemeinsam über das mittlere C hinweg — genau so, wie Klaviermusik notiert wird.",
    "rdx_ud_ac": "Kreuze, Be und Auflösungszeichen im Notensystem, dann Töne innerhalb von Tonarten.",
    "rdx_ud_ks": "Erkenne Dur- und parallele Moll-Tonarten anhand ihrer Vorzeichen auf einen Blick.",
    "rdx_ud_iv": "Erfasse den Abstand zweier Noten an ihrer optischen Gestalt, statt jeden Ton einzeln zu buchstabieren.",
    "rdx_ud_ch": "Erkenne Dreiklänge und ihr Tongeschlecht, gefolgt von ihren Umkehrungen.",
    "rdx_ud_rh": "Tippe Rhythmen passgenau zum Metronom; das Timing wird auf die Millisekunde genau gemessen.",
    "rdx_ud_cc": "Alt- und Tenorschlüssel für Viola-, Cello- und Posaunenstimmen.",
    "rdx_ud_sr": "Frisch generierte Melodien zum Blattspiel, in deinem eigenen Tempo oder im Takt.",
    "rdx_ty_iv": "Intervall benennen",
    "rdx_ty_ch": "Akkord benennen",
    "rdx_ty_ks": "Tonart benennen",
    "rdx_ty_rh": "Rhythmus",
    "rdx_ty_sr": "Vom-Blatt-Spiel",
    "rdx_d_name": "Eine Note erscheint auf dem Notensystem — wähle ihren Namen so schnell wie möglich. Genauigkeit zählt zuerst, dann Geschwindigkeit.",
    "rdx_d_play": "Eine Note erscheint auf dem Notensystem — spiele sie auf deinem MIDI-Keyboard, den Bildschirmtasten oder der Computertastatur (A–K). Die genaue Oktave zählt bei MIDI und den hier gezeigten Tasten.",
    "rdx_d_k2s": "Eine Taste leuchtet auf der Klaviatur auf — finde die passende Note auf dem Notensystem unter den Optionen.",
    "rdx_d_iv": "Zwei Noten erscheinen — benenne das Intervall zwischen ihnen (Sekunde bis Oktave). Lies das Notenbild: Linie-zu-Linie oder Zwischenraum-zu-Zwischenraum bedeutet ein ungerades Intervall.",
    "rdx_d_ch": "Ein Dreiklang erscheint — benenne Grundton und Tongeschlecht. Du kannst ihn auch spielen.",
    "rdx_d_ks": "Generalvorzeichen erscheinen — benenne die Dur-Tonart (die parallele Moll-Tonart wird unter jeder Antwort angezeigt).",
    "rdx_d_rh": "Lies einen zweitaktigen Rhythmus, höre den Einzähler und tippe dann jede Note im Takt (Leertaste, TIPPEN-Schaltfläche oder eine beliebige Taste auf deinem MIDI-Keyboard).",
    "rdx_d_sr": "Eine neue Melodie wird für dich notiert. Spiele sie Schritt für Schritt (die Partitur wartet auf dich) oder im Takt mit dem Metronom für eine Wertung.",
