    "an_limits": "MusicXML (.musicxml, .xml o .mxl compresso) preserva la notazione originale. I file MIDI vengono ricostruiti come notazione sulla griglia ritmica scelta (1/16 per impostazione predefinita); le mani seguono le tracce MIDI se chiaramente distinte, altrimenti si dividono per registro. L'armatura presente nel file viene mantenuta; se assente, la tonalità viene stimata e può essere modificata manualmente. L'indicazione di tempo mancante assume 4/4 come valore predefinito. Le variazioni di tempo vengono rispettate durante la riproduzione; i ritornelli non vengono espansi. I file PDF non sono supportati.",
    "an_title": "Partitura e analisi",
