    "sym_ottavabassa": "Ottava bassa (8vb) — suonare un'ottava sotto le note scritte per tutta l'estensione del segno",
    "sym_tuplet": "Gruppo irregolare — eseguire il gruppo numerato nella durata normalmente occupata da un diverso numero di note dello stesso valore; una terzina mette tre note nel tempo di due",
