    "sym_accidental_flat": "Bemolle (♭) — abbassare questa nota di un semitono rispetto alla sua altezza naturale",
    "sym_accidental_natural": "Bequadro (♮) — annullare un diesis o bemolle e riportare la nota all'altezza naturale",
