    "pr_hint": "Una sessione di pratica mirata si apre qui e utilizza la tastiera sottostante per rispondere.",
    "ex_staff_hint": "Le stesse note in entrambe le chiavi — basso a sinistra, violino a destra, come sulla tastiera. Le note troppo acute o troppo gravi per il pentagramma sono indicate accanto a una freccia.",
