    "ex_title": "Esplora",
    "ex_lede": "Suona liberamente — Étude riconosce in tempo reale ciò che suoni. Apri la scheda Circolo delle quinte per ascoltare scale o accordi di ogni tonalità con la diteggiatura per entrambe le mani.",
