    "an_harm_note": "Cada acorde dura o compasso inteiro a menos que as notas mudem claramente de harmonia num tempo, e é identificado a partir de todas as notas que soam, ponderadas por duração e posição métrica. Exato: todas as notas do acorde soam e nenhuma outra leitura se aproxima. Provável: o melhor encaixe, embora falte uma nota, soem outras notas ou outra leitura seja próxima. Sugerido: ambíguo; alternativas são exibidas. Notas estranhas são classificadas por aproximação, resolução e sobreposição harmônica.",
