    "an_tip": "As tonalidades são estimadas com perfis Krumhansl–Kessler ponderados pela duração, distinguindo entre tom maior e sua relativa menor; o valor r mostra o quão claro é o encaixe. Os acordes são comparados tempo a tempo com modelos ponderados pela duração, de modo que notas de passagem diminuem a confiança em vez de anular o acorde. Numerais romanos seguem a tonalidade escrita ou escolhida. Clique num acorde ou motivo para selecionar suas notas.",
